class Solution {
public:
 bool canChoose(vector<vector<int>>& groups,vector<int>& nums){
  int i=0,n=nums.size();
  for(auto& g:groups){bool found=false;
   while(i+(int)g.size()<=n){bool ok=true;
    for(int j=0;j<(int)g.size();++j)if(nums[i+j]!=g[j]){ok=false;break;}
    if(ok){i+=g.size();found=true;break;}++i;
   }
   if(!found)return false;
  }return true;
 }
};
